<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
require_admin();
require __DIR__ . '/anamnesis-bootstrap.php';
require __DIR__ . '/patient-layout.php';

$pdo = db(); $message = ''; $error = '';
$editId = (int)($_GET['edit'] ?? $_POST['anamnesis_question_id'] ?? 0);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string)($_POST['action'] ?? 'save_question'); $id = (int)($_POST['anamnesis_question_id'] ?? 0);
    if ($action === 'save_print_settings') {
        $headerColor = preg_match('/^#[0-9a-fA-F]{6}$/', (string)($_POST['header_color'] ?? '')) ? (string)$_POST['header_color'] : '#14843c';
        save_anamnesis_print_settings([
            'title' => mb_substr(trim((string)($_POST['print_title'] ?? 'VOX İ.M. - HASTA KARTI')), 0, 120),
            'header_color' => $headerColor,
            'font_size' => (string)max(9, min(16, (int)($_POST['font_size'] ?? 11))),
            'question_font_size' => (string)max(9, min(16, (int)($_POST['question_font_size'] ?? 11))),
            'page_margin' => (string)max(8, min(42, (int)($_POST['page_margin'] ?? 20))),
            'question_width' => (string)max(32, min(65, (int)($_POST['question_width'] ?? 46))),
            'yes_width' => (string)max(7, min(20, (int)($_POST['yes_width'] ?? 12))),
            'detail_width' => (string)max(12, min(30, (int)($_POST['detail_width'] ?? 20))),
            'row_height' => (string)max(20, min(50, (int)($_POST['row_height'] ?? 27))),
            'notes_height' => (string)max(28, min(80, (int)($_POST['notes_height'] ?? 37))),
            'footer_height' => (string)max(24, min(80, (int)($_POST['footer_height'] ?? 34))),
            'line_width' => (string)max(1, min(3, (int)($_POST['line_width'] ?? 1))),
            'layout' => mb_substr((string)($_POST['layout'] ?? ''), 0, 2000),
        ]);
        $message = 'Yazıcı çıktısı tasarımı kaydedildi.';
    } elseif ($action === 'delete_question') {
        $pdo->prepare('DELETE FROM anamnesis_question_definitions WHERE id=?')->execute([$id]); $message = 'Anamnez sorusu silindi.';
    } else {
        $name = trim((string)($_POST['name'] ?? '')); $active = isset($_POST['active']) ? 1 : 0; $sort = (int)($_POST['sort_order'] ?? 0);
        if ($name === '') $error = 'Soru alanı zorunludur.';
        else {
            $duplicate = $pdo->prepare('SELECT id FROM anamnesis_question_definitions WHERE name=? AND id<>?'); $duplicate->execute([$name, $id]);
            if ($duplicate->fetchColumn()) $error = 'Bu soru zaten kayıtlı.';
            elseif ($id) { $pdo->prepare('UPDATE anamnesis_question_definitions SET name=?,detail_label=?,active=?,sort_order=? WHERE id=?')->execute([$name,trim((string)($_POST['detail_label'] ?? '')),$active,$sort,$id]); $message='Anamnez sorusu güncellendi.'; }
            else { $pdo->prepare('INSERT INTO anamnesis_question_definitions(name,detail_label,active,sort_order) VALUES(?,?,?,?)')->execute([$name,trim((string)($_POST['detail_label'] ?? '')),$active,$sort]); $message='Anamnez sorusu eklendi.'; }
        }
    }
}
$edit = ['id'=>0,'name'=>'','detail_label'=>'','active'=>1,'sort_order'=>0];
if ($editId) { $statement=$pdo->prepare('SELECT * FROM anamnesis_question_definitions WHERE id=?'); $statement->execute([$editId]); $edit=$statement->fetch() ?: $edit; }
$rows = anamnesis_question_definitions();
$printSettings = anamnesis_print_settings();
patient_header('Ayarlar - Anamnez', 'settings');
?>
