</style>
<script>(()=>{const form=document.querySelector('.print-design-form'),canvas=form?.querySelector('.a4-designer'),hidden=form?.querySelector('[name="layout"]');if(!form||!canvas||!hidden)return;let layout={};try{layout=JSON.parse(hidden.value||'{}')}catch(_){layout={}};const defaults={header:{x:8,y:7},meta:{x:8,y:17},questions:{x:8,y:27},footer:{x:8,y:91}};layout={...defaults,...layout};const place=block=>{const key=block.dataset.designBlock,position=layout[key]||defaults[key];block.style.left=position.x+'%';block.style.top=position.y+'%'};canvas.querySelectorAll('.design-block').forEach(block=>{place(block);let start=null;block.addEventListener('pointerdown',event=>{event.preventDefault();block.setPointerCapture(event.pointerId);const rect=canvas.getBoundingClientRect(),position=layout[block.dataset.designBlock]||defaults[block.dataset.designBlock];start={x:event.clientX,y:event.clientY,left:position.x,top:position.y,rect};});block.addEventListener('pointermove',event=>{if(!start)return;const key=block.dataset.designBlock,maxX=100-(block.offsetWidth/start.rect.width*100),maxY=100-(block.offsetHeight/start.rect.height*100);layout[key]={x:Math.max(0,Math.min(maxX,start.left+(event.clientX-start.x)/start.rect.width*100)),y:Math.max(0,Math.min(maxY,start.top+(event.clientY-start.y)/start.rect.height*100))};place(block);});const finish=()=>{if(!start)return;start=null;hidden.value=JSON.stringify(layout)};block.addEventListener('pointerup',finish);block.addEventListener('pointercancel',finish);});})();</script>
<script>(()=>{const form=document.querySelector('.print-design-form'),canvas=form?.querySelector('.a4-designer'),hidden=form?.querySelector('[name="layout"]');if(!form||!canvas||!hidden)return;const snap=block=>{let layout={};try{layout=JSON.parse(hidden.value||'{}')}catch(_){}const key=block.dataset.designBlock,position=layout[key];if(!position)return;position.x=Math.round(position.x/5)*5;position.y=Math.round(position.y/5)*5;hidden.value=JSON.stringify(layout);block.style.left=position.x+'%';block.style.top=position.y+'%'};canvas.querySelectorAll('.design-block').forEach(block=>block.addEventListener('pointerup',()=>snap(block)));const preview=document.createElement('div');preview.className='print-preview-modal';preview.hidden=true;preview.innerHTML='<section class="print-preview-sheet"><button type="button" aria-label="Kapat">×</button><div class="print-preview-block header"></div><div class="print-preview-block meta">Hasta Ad Soyad · Tarih</div><div class="print-preview-block questions">Sorular<br><br>☐ Evet &nbsp; Açıklama alanı<br><br>☐ Evet &nbsp; Açıklama alanı</div><div class="print-preview-block footer">VOX İşitme Cihazları</div></section>';document.body.append(preview);const showPreview=()=>{let layout={};try{layout=JSON.parse(hidden.value||'{}')}catch(_){}const title=form.querySelector('[name="print_title"]').value,color=form.querySelector('[name="header_color"]').value;preview.querySelector('.header').textContent=title;preview.querySelectorAll('.print-preview-block').forEach(block=>{const key=block.classList.contains('header')?'header':block.classList.contains('meta')?'meta':block.classList.contains('questions')?'questions':'footer',position=layout[key]||{x:8,y:8};block.style.left=position.x+'%';block.style.top=position.y+'%';});preview.querySelector('.header').style.color=color;preview.hidden=false;};form.querySelector('.print-preview-button')?.addEventListener('click',showPreview);preview.addEventListener('click',event=>{if(event.target===preview||event.target.closest('button'))preview.hidden=true});})();</script>
<script>(()=>{const form=document.querySelector('.print-design-form'),canvas=form?.querySelector('.a4-designer'),hidden=form?.querySelector('[name="layout"]');if(!form||!canvas||!hidden)return;const grid=5,read=()=>{try{return JSON.parse(hidden.value||'{}')}catch(_){return {}}},write=value=>hidden.value=JSON.stringify(value);canvas.querySelectorAll('.design-block').forEach(block=>{let layout=read(),position=layout[block.dataset.designBlock]||{};if(position.width)block.style.width=position.width+'%';if(position.height)block.style.height=position.height+'%';const handle=document.createElement('span');handle.className='design-resize-handle';block.append(handle);let start=null;handle.addEventListener('pointerdown',event=>{event.preventDefault();event.stopPropagation();handle.setPointerCapture(event.pointerId);const rect=canvas.getBoundingClientRect(),blockRect=block.getBoundingClientRect();start={x:event.clientX,y:event.clientY,rect,width:blockRect.width/rect.width*100,height:blockRect.height/rect.height*100};});handle.addEventListener('pointermove',event=>{if(!start)return;const layout=read(),key=block.dataset.designBlock,position=layout[key]||{};const maxWidth=100-(position.x||0),maxHeight=100-(position.y||0);position.width=Math.max(grid,Math.min(maxWidth,Math.round((start.width+(event.clientX-start.x)/start.rect.width*100)/grid)*grid));position.height=Math.max(grid,Math.min(maxHeight,Math.round((start.height+(event.clientY-start.y)/start.rect.height*100)/grid)*grid));layout[key]=position;block.style.width=position.width+'%';block.style.height=position.height+'%';write(layout);});const stop=()=>{start=null};handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop);});const questions=<?=json_encode(array_values(array_filter($rows, static fn(array $row): bool => (int)$row['active'] === 1)), JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;form.querySelector('.print-preview-button')?.addEventListener('click',()=>{const preview=document.querySelector('.print-preview-modal'),sheet=preview?.querySelector('.print-preview-sheet');if(!preview||!sheet)return;const layout=read();preview.querySelectorAll('.print-preview-block').forEach(block=>{const key=block.classList.contains('header')?'header':block.classList.contains('meta')?'meta':block.classList.contains('questions')?'questions':'footer',position=layout[key]||{};if(position.width)block.style.width=position.width+'%';if(position.height)block.style.height=position.height+'%';});const questionBlock=preview.querySelector('.questions');questionBlock.replaceChildren(...questions.map(question=>{const line=document.createElement('div');line.textContent='☐ ' + question.name + (question.detail_label ? ' — ' + question.detail_label : '');return line;}));});})();</script>
<script>(()=>{const form=document.querySelector('.print-design-form'),canvas=form?.querySelector('.a4-designer'),button=form?.querySelector('.print-preview-button');if(!form||!canvas||!button)return;button.addEventListener('click',()=>{const preview=document.querySelector('.print-preview-modal');if(!preview)return;const canvasRect=canvas.getBoundingClientRect();canvas.querySelectorAll('.design-block').forEach(source=>{const rect=source.getBoundingClientRect(),target=preview.querySelector('.'+source.dataset.designBlock);if(!target)return;target.style.setProperty('left',((rect.left-canvasRect.left)/canvasRect.width*100)+'%','important');target.style.setProperty('top',((rect.top-canvasRect.top)/canvasRect.height*100)+'%','important');target.style.setProperty('width',(rect.width/canvasRect.width*100)+'%','important');target.style.setProperty('height',(rect.height/canvasRect.height*100)+'%','important');});});})();</script>
<script>(()=>{const form=document.querySelector('.print-design-form'),button=form?.querySelector('.print-preview-button'),questions=<?=json_encode(array_values(array_filter($rows, static fn(array $row): bool => (int)$row['active'] === 1)), JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;if(!form||!button)return;button.addEventListener('click',()=>{const preview=document.querySelector('.print-preview-modal'),sheet=preview?.querySelector('.print-preview-sheet');if(!preview||!sheet)return;const value=name=>form.querySelector('[name="'+name+'"]').value,title=value('print_title'),color=value('header_color');sheet.replaceChildren();sheet.style.padding=value('page_margin')+'px';const close=document.createElement('button');close.type='button';close.textContent='×';sheet.append(close);const card=document.createElement('section');card.className='anamnesis-print-card';card.style.setProperty('--body-font',value('font_size')+'px');card.style.setProperty('--question-font',value('question_font_size')+'px');card.style.setProperty('--question-width',value('question_width')+'%');card.style.setProperty('--yes-width',value('yes_width')+'%');card.style.setProperty('--detail-width',value('detail_width')+'%');card.style.setProperty('--row-height',value('row_height')+'px');card.style.setProperty('--notes-height',value('notes_height')+'px');card.style.setProperty('--footer-height',value('footer_height')+'px');card.style.setProperty('--line-width',value('line_width')+'px');const heading=document.createElement('h1');heading.textContent=title;heading.style.color=color;card.append(heading);const table=document.createElement('table');const addRow=(cells,className='')=>{const row=document.createElement('tr');if(className)row.className=className;cells.forEach(cell=>{const td=document.createElement('td');td.textContent=cell.text||'';if(cell.colspan)td.colSpan=cell.colspan;if(cell.className)td.className=cell.className;row.append(td)});table.append(row)};addRow([{text:'AD SOYAD',colspan:2},{text:'TARİH'},{text:'',colspan:1}],'patient-row');addRow([{text:'ŞİKAYETİNİZ NEDİR ?',colspan:2},{text:'',colspan:2}]);addRow([{text:'KAÇ YILDIR ŞİKAYETİNİZ VAR',colspan:4}]);addRow([{text:'MESLEĞİNİZİ ÖĞRENEBİLİR MİYİZ',colspan:4}]);questions.forEach(question=>addRow([{text:question.name},{text:'□ EVET',className:'yes-cell'},{text:question.detail_label||''},{text:''}]));addRow([{text:'MEMLEKETİNİZ VE YAŞADIĞINIZ ŞEHİR',colspan:4}]);addRow([{text:'ODY OTOSKOPİK İNCELEME SONUCU',colspan:4}],'large-row');addRow([{text:'ODY GÖRÜŞ VE TAVSİYESİ',colspan:4}],'large-row');card.append(table);const footer=document.createElement('div');footer.className='print-card-footer';footer.textContent='VOX İşitme Cihazları';card.append(footer);sheet.append(card);preview.hidden=false;});})();</script>
<script>(()=>{const table=document.querySelector('.anamnesis-question-table');if(!table)return;const apply=row=>{row.style.setProperty('display','grid','important');row.style.setProperty('grid-template-columns','minmax(0, 2.35fr) minmax(0, 1.2fr) 48px 76px 128px','important');row.style.setProperty('width','100%','important');row.querySelectorAll('.question-column,.detail-column').forEach(cell=>{cell.style.setProperty('min-width','0','important');cell.style.setProperty('max-width','100%','important');cell.style.setProperty('white-space','normal','important');cell.style.setProperty('overflow-wrap','anywhere','important');cell.style.setProperty('word-break','break-word','important');});};table.querySelectorAll('thead tr,tbody tr').forEach(apply);})();</script>
<style>
  .print-preview-sheet:has(.anamnesis-print-card) { padding: 38px 60px 34px; box-sizing: border-box; }
  .anamnesis-print-card { height: 100%; box-sizing: border-box; border: var(--line-width, 1px) solid #111; color: #122542; font-family: Arial, sans-serif; font-size: var(--body-font, 8px); }
  .anamnesis-print-card h1 { margin: 0; padding: 12px 14px; border-bottom: calc(var(--line-width, 1px) * 2) solid #111; color: var(--print-title-color, #0d873d); font-family: Georgia, serif; font-size: 20px; line-height: 1; }
  .anamnesis-print-card table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .anamnesis-print-card td { height: var(--row-height, 27px); padding: 4px 9px; border-right: var(--line-width, 1px) solid #111; border-bottom: var(--line-width, 1px) solid #111; vertical-align: middle; overflow-wrap: anywhere; }
  .anamnesis-print-card td:last-child { border-right: 0; }
  .anamnesis-print-card tr td:nth-child(1) { width: var(--question-width, 46%); font-size: var(--question-font, 8px); }
  .anamnesis-print-card tr td:nth-child(2) { width: var(--yes-width, 12%); }
  .anamnesis-print-card tr td:nth-child(3) { width: var(--detail-width, 20%); }
  .anamnesis-print-card .yes-cell { text-align: center; font-weight: 700; }
  .anamnesis-print-card .patient-row td { height: 22px; font-size: 7px; }
  .anamnesis-print-card .large-row td { height: var(--notes-height, 37px); }
  .print-card-footer { height: var(--footer-height, 34px); display: flex; align-items: center; justify-content: center; font-weight: 700; }
  .print-settings-panel { display:grid; grid-template-columns:repeat(2,minmax(170px,1fr)); gap:14px; flex:1 1 390px; padding:18px; border:1px solid #e1e2e8; border-radius:8px; }
  .print-settings-panel h3 { grid-column:1/-1; margin:0; font-size:16px; }
  .print-settings-panel label input { min-width:0!important; width:100%; box-sizing:border-box; }
  .print-design-form .designer-help { flex-basis:100%; }
  @media(max-width:700px){.print-settings-panel{grid-template-columns:1fr;}.print-settings-panel h3{grid-column:auto;}}
</style>
